  ui_story_5057_50570101_78_dialog_content = "<color=#e8d9bb>กิ่งไม้และพุ่มไม้ข่วนขาของลอเรไล ทำให้เลือดไหลเล็กน้อย ข้อเท้าของเธอบวมและงออย่างชัดเจน</color>",
  ui_story_5057_50570101_79_dialog_content = "ไม่ต้องเสียใจเรื่องนั้นตอนนี้ ตอนนี้เราต้องไปดูว่าคุณมีกระดูกหักหรือไม่",
  ui_story_5057_50570101_80_dialog_content = "เอาสิ... เรากลับกันดีกว่า ช่วยหาล็อกบันทึกให้ฉันใช้เป็นไม้กันเจ็บได้มั้ย?",
  ui_story_5057_50570101_81_dialog_content = "คุณพูดอะไรนะ? คุณยังไม่สามารถยืนขึ้นมาตอนนี้เลย.",
  ui_story_5057_50570101_82_dialog_content = "การพยายามเดินกลับจะทำให้บาดแผลร้ายแรงขึ้นเท่านั้น",
  ui_story_5057_50570101_83_dialog_content = "<color=#e8d9bb>ฉันหันหลังให้กับ Lorelei และย่อตัวลง</color>",
