  ui_story_5057_50570101_85_dialog_content = "ฉันเป็นผู้ใหญ่ ฉันเดินด้วยตัวเองได้ เด็ก ๆ ถึงต้องถือไว้บนหลังคนอื่น...",
  ui_story_5057_50570101_86_dialog_content = "แต่ฉันคิดว่าคนที่แสร้งทำตัวเป็นผู้ใหญ่นั้นก็คือเด็ก ๆ จริง ๆ",
