  ui_story_5057_50570101_96_dialog_content = "<color=#e8d9bb>ขณะที่เรากลับบ้าน โลเรไลหลับอยู่บนหลังของฉัน พูดในฝันอย่างแปลกประหลาดและไม่สามารถเข้าใจได้ตลอดทาง</color>",
