  ui_story_5057_50570102_5_dialog_content = "ตอนนี้ดีแล้ว! อย่าดูถูกความสามารถในการฟื้นฟูของฉัน แน่นอนว่าคุณก็มีส่วนช่วยในการฟื้นตัวด้วย",
