  ui_story_5057_50570102_7_dialog_content = "แม้ว่าฉันจะไม่เป็น ฉันก็ไม่ได้ทิ้งคุณไว้คนเดียวหรอก คุณเป็นเพื่อนสำคัญสำหรับฉัน",
