  ui_story_5057_50570102_9_dialog_content = "ย่อมมีสินค้าพิเศษเพียบในอีราเวลใช่มั้ย? เราควรเป็นคู่หูทางธุรกิจกัน!",
  ui_story_5057_50570102_10_dialog_content = "การเป็นผู้ช่วยของฉันอาจจะเสียเสน่ห์สำหรับคุณ ดังนั้นเราจะร่วมมือกันเป็นพาร์ทเนอร์กันเถอะ?",
