  ui_story_5057_50570102_17_dialog_content = "ฮ่าฮ่า... จริงๆ นะ มีคนเยอะเลยในอัมบราตันที่สามารถทำได้",
  ui_story_5057_50570102_18_dialog_content = "แต่นั่นไม่ใช่ประเด็น! วันนี้เราจะวางเทพี Denuo ไว้ในความสำคัญที่น้อยลงกัน",
