  ui_story_5057_50570102_24_dialog_content = "นี่เป็นพื้นที่ลับของสวนน้ำ มันน่าอัศจรรย์ใช่ไหม? ฉันไม่คิดว่าคุณเคยมาที่นี่มาก่อน",
