  ui_story_5057_50570102_66_dialog_content = "เข้าใจแล้วเหรอคุณ? การเชิญคุณเข้าสู่สนามเด็กเล่นส่วนตัวของฉันคือการยอมรับความเชื่อมโยงของเรา",
  ui_story_5057_50570102_67_dialog_content = "อย่างนี้นี่เอง! คุณไม่ใช่แค่เจ้าของร้านของฉันเท่านั้น แต่ยังเป็นเพื่อนที่ยอดเยี่ยมด้วย ฉันรู้สึกอยู่ตั้งแต่แรกเลย",
