  ui_story_5057_50570102_78_dialog_content = "...",
  ui_story_5057_50570102_79_dialog_content = "(เธอกำลังกินอาหารอยู่และสถานการณ์ดูเครียดมาก... เธอยังคงโกรธฉันอยู่เหรอ?)",
  ui_story_5057_50570102_80_dialog_content = "(อาหารอร่อยมาก แต่นี่คือครั้งแรกที่เห็นเธอกินโดยไม่พูดคำใดๆ)",
