  ui_story_5057_50570102_87_dialog_content = "ฉันไม่ได้หมายความว่าฉันไม่ต้องการเป็นเพื่อนของคุณ, PlayerName.",
  ui_story_5057_50570102_88_dialog_content = "เพียงแค่ฉันต้องการนำเสนอตัวเองให้ดูเป็นคนทำธุรกิจที่เติบโต ไม่ใช่คนที่แค่ชอบอยู่กับเพื่อนๆเหมือนเด็กน้อย",
  ui_story_5057_50570102_89_dialog_content = "ฉันต้องการให้ตัวเองหยุด—",
  ui_story_5057_50570102_90_option_content = "เข้าใจ",
  ui_story_5057_50570102_91_dialog_content = "ฉันเข้าใจว่าคุณพยายามที่จะสร้างชื่อเสียงให้คนอื่นรู้จักในฐานะบุคคลที่อิสระ",
  ui_story_5057_50570102_92_dialog_content = "แต่... ฉันยังไม่ใช่ผู้ใหญ่เลย! เมื่อคุณอยู่กับฉัน คุณไม่จำเป็นต้องแสดงตัวเป็นผู้ใหญ่ แค่ผ่อนคลายและเป็นตัวของคุณเองก็พอ",
  ui_story_5057_50570102_93_dialog_content = "ขอบคุณนะ PlayerName...",
  ui_story_5057_50570102_94_option_content = "ไม่เป็นไร",
  ui_story_5057_50570102_95_dialog_content = "ฉันเข้าใจนะ ไม่ต้องห่วง ฉันจะไม่เอาใจใส่ มันเป็นเรื่องปกติสำหรับเพื่อนที่จะทะเลาะกันบ้าง!",
  ui_story_5057_50570102_96_dialog_content = "คุณยังยินดีที่จะเป็นเพื่อนกับฉันใช่ไหม? ขอบคุณนะ PlayerName.",
  ui_story_5057_50570102_97_dialog_content = "<color=#e8d9bb>หลังจากนั้น ลอร์เลย์กลับมาเป็นตัวเองเหมือนเดิม ขำขันและคุยกับฉันขณะที่เราสนุกกับอาหาร นอกจากนี้เธอยังคอยคุยกับฉันจนสายดึก</color>",
  ui_story_5057_50570201_1_dialog_content = "เฮ้ย, ฉันเดาว่าคุณคือผู้ช่วยที่ Lorelei พูดถึงใช่ไหม?",
  ui_story_5057_50570201_2_dialog_content = "เฮ้ย, ฉันเดาว่า Cena เป็นคนที่ได้รับความช่วยเสียงจาก Lorelei ใช่มั้ย?",
  ui_story_5057_50570201_3_dialog_content = "โอ้ คุณกำลังเลียนแบบฉันเหรอ เคเลสไทต์",
  ui_story_5057_50570201_4_dialog_content = "ทำไมล่ะ? คุณกำลังพยายามสะกดใจด้วยเสน่ห์และความสุภาพของผู้ชายที่น่าสนใจเหมือนฉันหรือเปล่า?",
  ui_story_5057_50570201_5_dialog_content = "แต่มันไม่เหมาะกับหมวดหมู่อายุของคุณเคเลสไทต์",
  ui_story_5057_50570201_6_dialog_content = "ไม่ใช่แบบนั้นนะครับ",
  ui_story_5057_50570201_7_dialog_content = "อย่าเป็นคนหลงตัวเอง! ฉันแค่พูดเย้ยหยันเท่านั้นเอง",
  ui_story_5057_50570201_8_dialog_content = "ฉันไม่สนใจเสน่ห์ของคุณหรืออะไรก็ตาม",
  ui_story_5057_50570201_9_dialog_content = "งั้นเหรอ? มีสุภาพสตรีเยอะที่จะปฏิเสธนะ",
  ui_story_5057_50570201_10_dialog_content = "คุณจะประสบปัญหาในความสัมพันธ์ในไม่ช้าหากคุณมีทัศนคติแบบนั้น",
  ui_story_5057_50570201_11_dialog_content = "ฮ่าฮ่าฮ่า นั่นคือคำพูดแปลกๆ",
  ui_story_5057_50570201_12_dialog_content = "ถ้าคุณถามฉัน ความเจ็บปวดจากการถูกปฏิเสธเป็นความจริงในชีวิตที่เราทั้งหมดต้องแชร์กัน",
  ui_story_5057_50570201_13_dialog_content = "ชีวิตสั้น ดังนั้น สนุกสนานเถอะ!",
  ui_story_5057_50570201_14_dialog_content = "ฉันไม่เชื่อเรื่องนั้น แม้แต่คนที่เป็นแคชชวลที่สุดก็ยังมีความรู้สึกและปรารถนารักษารักใคร่สัมพันธ์ที่เสถียรและสามัคคี",
