  ui_story_5057_50570201_18_dialog_content = "ตามคำกล่าวที่ว่า \"สิ่งต่าง ๆ เปลี่ยนแปลง และไม่มีอะไรคงที่\"",
  ui_story_5057_50570201_19_dialog_content = "สิ่งที่ฉันรักคือการเดินทางและลองสัมผัสประสบการณ์ต่าง ๆ",
  ui_story_5057_50570201_20_dialog_content = "ความสัมพันธ์ที่คงที่นำไปสู่การมัดขาดปีกของฉันเท่านั้น",
  ui_story_5057_50570201_21_dialog_content = "งั้นรึ...",
  ui_story_5057_50570201_22_dialog_content = "ยิ่งคุณพยายามแสดงตัวเองว่าเป็นคู่รักที่ยอดเยี่ยม ยิ่งแสดงให้เห็นว่าคุณพึ่งพาหน้ากากที่น่าสนใจเพื่อหลีกเลี่ยงการเผชิญหน้ากับความเป็นจริง",
  ui_story_5057_50570201_23_dialog_content = "อะแฮ่ม",
  ui_story_5057_50570201_24_dialog_content = "นี่เป็นเหตุผลว่าทำไมคุณเคเลสไทต์ถึงเป็นปัญหา",
  ui_story_5057_50570201_25_dialog_content = "รหัสความเงียบเงินก็เป็นตัววัดความเป็นผู้ใหญ่ของคนใหญ่ด้วยนะคุณ มิเช่นนั้น ชีวิตก็ไม่มีความสุข",
  ui_story_5057_50570201_26_dialog_content = "โอ้ ฉันกำลังคิดว่ามันน่าหลงใหลขนาดไหนที่มีผู้หญิงที่น่ารักมาให้ฉันยืมมือ เปลี่ยนเวลาที่เราอยู่ด้วยกันให้กลายเป็นวันที่แสนโรแมนติก",
  ui_story_5057_50570201_27_dialog_content = "แต่ตอนนี้ฉันต้องเสียความสุขกับเด็กหัวฉิ่งที่อ่านใจคนได้",
  ui_story_5057_50570201_28_dialog_content = "เราไปรับรอบหนึ่งหรือสองกันเถอะ อาจจะช่วยลดพลังจิตของคุณลงบ้างนะ?",
  ui_story_5057_50570201_29_dialog_content = "ฉันอยู่ที่นี่เพื่อทำงาน ไม่ใช่นัดเดทหรือดื่มเหล้าเหมือนคนบางคน",
  ui_story_5057_50570201_30_dialog_content = "ทำงาน?",
  ui_story_5057_50570201_31_dialog_content = "ยังเป็นเช้าอยู่ ยังไม่ถึงเวลาทำงานเลย! ไปสนุกกันก่อนเถอะ",
  ui_story_5057_50570201_32_dialog_content = "ฉันรู้สถานที่ที่ดีที่สุดที่จะทำให้คุณประหลาดใจแน่นอน",
  ui_story_5057_50570201_33_dialog_content = "มังกรคืนขาว... แน่นอนว่าเป็นสถานที่ที่จะทำให้ใจฉันตะลึง",
