  ui_story_5057_50570201_35_dialog_content = "ขอโทษนะ, PlayerName, ฉันไม่สนใจที่จะขี่ร่วมกับเด็กวัยรุ่นเช่นคุณ",
  ui_story_5057_50570201_36_dialog_content = "แล้วข้อเสนอคืออะไร...",
  ui_story_5057_50570201_37_option_content = "เอาไงดีล่ะ?",
  ui_story_5057_50570201_38_dialog_content = "เย็น ฉันเลือกเป้าหมายคนแรกไว้แล้ว",
  ui_story_5057_50570201_39_dialog_content = "ตาของฉันคมเท่านกอินทรีที่ได้รับการฝึก...",
