  ui_story_5057_50570201_41_dialog_content = "(ฉันมองไปทางนั้นและเห็นแม่คนสวยอ่อนวัยที่กำลังจะต่อคิวพร้อมกับเด็กผู้ชายและพี่สาวน้อยของเขา)",
  ui_story_5057_50570201_42_dialog_content = "(พวกเขาดูมีความสุขมากแม้จะยืนอยู่ท่ามกลางฝูงชนที่แน่นขนัด)",
  ui_story_5057_50570201_43_dialog_content = "คุณไม่ได้จะแอบแซ่บใช่ไหม?",
  ui_story_5057_50570201_44_dialog_content = "ต้องเข้าใจมากกว่านี้นะ",
  ui_story_5057_50570201_45_dialog_content = "สวัสดีค่ะ ท่านหญิงที่น่ารัก เหล่านี้เป็นลูกของคุณหรือคะ? เด็กๆดูเหมือนจะสนใจของเล่นขนาดใหญ่มากค่ะ",
