  ui_story_5057_50570201_47_dialog_content = "ในฐานะผู้จัดการรีสอร์ต Denuo Valley ฉันยินดีที่ได้ยินเรื่องนี้!",
  ui_story_5057_50570201_48_dialog_content = "ดังนั้นฉันต้องการให้คุณและสองแขกเยาว์ได้สนุกสนานอย่างเต็มที่กับเงินที่คุณจ่าย!",
  ui_story_5057_50570201_49_dialog_content = "นี่คือบัตรส่วนลด VIP สามใบสำหรับคุณ",
  ui_story_5057_50570201_50_dialog_content = "โอ้, ผู้จัดการ, คุณน่าอัศจรรย์มาก... เฮ่!",
  ui_story_5057_50570201_51_dialog_content = "ดูแลผู้หญิงคนนี้และพี่น้องให้ดี PlayerName!",
  ui_story_5057_50570201_52_dialog_content = "<color=#e8d9bb>อย่างเฉียบพลัน เซน่าดันสามคนมาทางฉัน และรวดเร็วตามไปหาสองคนที่เพิ่งชิงกระเป๋ามือของแม่</color>",
  ui_story_5057_50570201_53_dialog_content = "เอ๊ะ",
  ui_story_5057_50570201_54_dialog_content = "อย่าได้คิดหนีเชียวนะ",
  ui_story_5057_50570201_55_dialog_content = "<color=#e8d9bb>ซีนาเตะที่เอวของโจรที่ใกล้ที่สุด</color>",
  ui_story_5057_50570201_56_dialog_content = "<color=#e8d9bb>ขโมยที่ถูกเตะบินไปกระแทกเพื่อนของเขาที่อยู่ด้านขวา และทั้งคู่ก็หกล้มลงด้วยกัน</color>",
  ui_story_5057_50570201_57_dialog_content = "คุณ-หนอยย!",
  ui_story_5057_50570201_58_dialog_content = "ฉันสามารถจับคุณได้ในที่สุด คุณกล้ามากที่จะตั้งเป้าหมายท่านหญิงใต้การดูแลของฉัน",
  ui_story_5057_50570201_59_dialog_content = "แต่ไม่เป็นไรครับ/ค่ะ คุณมีเวลาทั้งหมดในโลกใบนี้ให้เสียใจแล้ว",
  ui_story_5057_50570201_60_dialog_content = "ขอบคุณมาก!",
  ui_story_5057_50570201_61_dialog_content = "นี่เป็นหน้าที่ของฉัน พวกเราให้ความสำคัญกับความปลอดภัยของแขกทุกคนในรีสอร์ทเหนือสิ่งอื่นทั้งหมด",
  ui_story_5057_50570201_62_dialog_content = "โดยเฉพาะอย่างยิ่งสำหรับท่านหญิงที่สวยงามเช่นคุณ",
  ui_story_5057_50570201_63_dialog_content = "ถูกต้องแล้วครับ เราสามารถออกไปได้แล้วครับ น้องเคเลสไทต์",
  ui_story_5057_50570201_64_dialog_content = "เมื่อเทียบกับฉันที่เคยจับขโมยตำนานเมื่อเป็นนักสืบส่วนตัว คุณทำได้ดีพอควรแล้ว",
  ui_story_5057_50570201_65_dialog_content = "เย่! ภูมิใจในตัวเองนะครับ/ค่ะ!",
