  ui_story_5057_50570201_67_dialog_content = "<color=#e8d9bb>หลังจากนั้น เซน่าเชิญฉันไปทานอาหารค่ำ พวกเรากินอาหารอย่างอิ่มอร่อยในขณะที่เขาพูดไปมาเรื่องความสวยงามและมีเสน่ห์ของท่านหญิงคนนั้น</color>",
  ui_story_5057_50570201_68_dialog_content = "<color=#e8d9bb>อย่างไรก็ตาม เขาก็ยังไม่เปลี่ยนความรักนั้นเป็นการกระทำ และเรื่องราวของเซน่ากับท่านหญิงคนนั้นก็สิ้นสุดลงอย่างงั้น</color>",
  ui_story_5057_50570202_1_dialog_content = "อรุณสวัสดิ์",
  ui_story_5057_50570202_2_dialog_content = "อรุณสวัสดิ์ เคเลสไทต์",
  ui_story_5057_50570202_3_dialog_content = "คุณกำลังทำอะไรในสถานที่เช่นนี้ในตอนเช้าตรู่? ฉันตามหาคุณทุกที่",
  ui_story_5057_50570202_4_dialog_content = "ฉันจะอยู่ที่ไหนนอกจากที่บาร์? ออกไปเที่ยวในสระน้ำ? นั่นไม่ดีสำหรับผิวของฉัน",
  ui_story_5057_50570202_5_dialog_content = "ฉันหมายความว่าคุณไม่มีงานทำใช่ไหม",
  ui_story_5057_50570202_6_dialog_content = "คุณพยายามให้ฉันงานขี้เกียจกับคุณอย่างชัดเจนมาก จนมันจะเป็นปาฏิหาริย์ถ้า Lorelei ไม่หักเงินเดือนของฉัน...",
  ui_story_5057_50570202_7_dialog_content = "ฮ่าฮ่าฮ่า คุณเยี่ยมในทุกด้านเลย นอกจากการเป็นคนเครียดเกินไป",
  ui_story_5057_50570202_8_dialog_content = "คุณไม่รู้หรือว่าต้องมีชีวิตอยู่อย่างเต็มที่? ด้วยเงินที่น้อยมากที่ Lorelei จ่ายให้ฉัน ฉันยิ่งได้ผลกว่าถ้าอยู่ในบาร์ รอความสัมพันธ์ที่น่าทึ่ง",
  ui_story_5057_50570202_9_dialog_content = "งั้น \"เธอ\" ที่คุณกำลังรอคือเมื่อไหร่ที่จะปรากฏตัว?",
  ui_story_5057_50570202_10_dialog_content = "เฮ้ย, นำใจของคุณออกจากท่อระบายน้ำเถอะเคเลสไทต์",
  ui_story_5057_50570202_11_dialog_content = "อย่าเป็นคนผิวเผินเกินไป การสร้างมิตรภาพก็สวยงามเช่นกัน",
  ui_story_5057_50570202_12_dialog_content = "ฉันตกใจไม่น้อยที่คุณสามารถหมุนมันให้เป็นความผิดของฉันได้",
  ui_story_5057_50570202_13_dialog_content = "ฮ่าฮ่าฮ่า คุณเป็นคนที่น่าสนใจจริงๆ",
  ui_story_5057_50570202_14_dialog_content = "อย่ายืนอยู่ที่นั่นเฉยๆ มาที่นี่สิ ฉันไม่ได้จะกินคุณอยู่ดีหรอก",
  ui_story_5057_50570202_15_dialog_content = "อย่าบอกฉันว่าคุณกลัวความซับซ้อนของฉัน... หรือคุณแค่ไม่ชอบลักษณะของครึ่งมนุษย์ที่ฉันมี?",
  ui_story_5057_50570202_16_dialog_content = "ไม่จริงนะ!",
  ui_story_5057_50570202_17_dialog_content = "ดีมากจ๊ะ เด็กดี ขอบคุณที่ไม่กลัวคนออโรเรียนเช่นฉันเลยครับ!",
