  ui_story_5057_50570501_89_dialog_content = "<color=#e8d9bb>จากนั้นในบรรยากาศที่ละเอียดอ่อน ฉันได้รับประทานอาหารค่ำกับฟลอรีน คือเธอโกรธหรืออะไรเช่นนั้น...?</color>",
  ui_story_5057_50570502_1_dialog_content = "ขอบคุณสำหรับสิ่งที่คุณทำให้นะ ฟลอรีน",
  ui_story_5057_50570502_2_dialog_content = "เอ๊ะ",
  ui_story_5057_50570502_3_dialog_content = "คุณเพิ่งช่วยชีวิตฉัน",
  ui_story_5057_50570502_4_dialog_content = "ฉันจะไปเอาปลามาย่างหรือทำเป็นหม้อไฟหลงโจวที่ฉันได้เรียนรู้เมื่อคราวที่แล้วเพื่อเลี้ยงคุณ",
  ui_story_5057_50570502_5_dialog_content = "ฉันไม่คาดคิดว่ามันจะแข็งแรงขนาดนี้...",
  ui_story_5057_50570502_6_dialog_content = "ไม่เป็นไรน่า เรื่องเล็กน้อย",
  ui_story_5057_50570502_7_dialog_content = "แต่ลืมความคิดนั้นเถอะ ปลาตัวนั้นใหญ่พอที่จะกลืนเราทั้งสอง",
  ui_story_5057_50570502_8_dialog_content = "เอ๊ะ",
  ui_story_5057_50570502_9_dialog_content = "(ทำไมปลาที่อันตรายอยู่ที่นี่นะ?)",
  ui_story_5057_50570502_10_dialog_content = "โชคดีที่ฉันเลือกเรียนวิชาช่วยเหลือเบื้องต้นในภาคการศึกษาที่สองที่อุษาวิทยาลัยดอน",
  ui_story_5057_50570502_11_dialog_content = "อะแฮ่ม ทั้งๆ ที่แทบไม่มีใครเลือกวิชาและถูกมองข้ามไปเสียหมด",
  ui_story_5057_50570502_X11_dialog_content = "ฉันเชื่อว่าความรู้ใด ๆ ที่ช่วยชีวิตมีค่า",
  ui_story_5057_50570502_12_dialog_content = "ฉันอธิษฐานว่าฉันจะไม่ต้องใช้ความรู้นี้ แต่สุดท้าย PlayerName กลับเป็นเหยื่อจมน้ำคนแรกที่ฉันช่วยชีวิตได้",
  ui_story_5057_50570502_13_dialog_content = "การช่วยเสียชีวิตจากการจมน้ำ... ฉันจำได้ว่าโซรอซสอนฉันเรื่องนี้",
  ui_story_5057_50570502_14_dialog_content = "PlayerName คุณยังจำวิธีช่วยเหลือคนที่กำลังจมน้ำได้หรือไม่?",
  ui_story_5057_50570502_15_dialog_content = "ขั้นแรกคุณต้องนำคนที่จมน้ำออกจากน้ำ",
  ui_story_5057_50570502_16_dialog_content = "จากนั้นตรวจสอบว่าพวกเขายังหายใจอยู่และมีชีพจรหรือไม่",
  ui_story_5057_50570502_17_dialog_content = "ถ้าไม่เป็นอย่างนั้น ให้ดำเนินมาตรการทันทีเช่น การกดที่หน้าอกและการหายใจช่วยเหลือจนกว่าเขาจะฟื้นความสำนึกหรือมีผู้ช่วยเสริมมืออาชีพมาถึง",
  ui_story_5057_50570502_18_dialog_content = "นอกจากนี้ ควรเก็บหัวของเขาต่ำกว่าร่างกายเพื่อป้องกันอาการคลื่นไส้จากการเข้าสู่ทางเดินหายใจ",
  ui_story_5057_50570502_19_dialog_content = "อีกครั้งเหรอ โซรอซ? ไม่ว่าคุณจะสอนฉันกี่ครั้งก็ตาม ฉันก็ไม่มีโอกาสได้ใช้มัน...",
  ui_story_5057_50570502_20_dialog_content = "สู้ๆ นะครับ PlayerName ผมหวังว่าคุณจะไม่ต้องใช้ของเหล่านี้เลยครับ",
  ui_story_5057_50570502_21_dialog_content = "แต่หากเกิดเหตุการณ์ที่ไม่คาดคิดขึ้น ฉันหวังว่าคุณจะสามารถช่วยคนที่คุณรักด้วยความรู้นี้",
  ui_story_5057_50570502_22_dialog_content = "อืมม ขอคิดก่อนนะ...",
  ui_story_5057_50570502_23_dialog_content = "ฉันนอนอยู่บนขาของคุณใช่มั้ย?",
  ui_story_5057_50570502_24_dialog_content = "เรียบร้อยแล้ว เพราะคุณหายใจอีกครั้ง",
  ui_story_5057_50570502_25_dialog_content = "หายใจอีกแล้วเหรอ? นั่นหมายความว่าฉันหยุดหายใจ...",
  ui_story_5057_50570502_26_option_content = "เลยต้อง...!",
  ui_story_5057_50570502_27_dialog_content = "ฉัน-มันเป็นเพียงกระบวนการทางการแพทย์ปกติเท่านั้น ไม่ต้องตะโกน!",
  ui_story_5057_50570502_28_dialog_content = "ฉันทำแค่นั้นเพราะคุณตกลงน้ำโดยไม่ได้ตั้งใจ...",
