  ui_story_5057_50570502_31_option_content = "เพราะฉะนั้นฉันก็กลับมาหายใจเองเป็นปกติอีกครั้ง!",
  ui_story_5057_50570502_32_dialog_content = "ใช่แล้ว ใครรู้ล่ะ คุณอาจจะเป็นปลาจริง ๆ นะ",
  ui_story_5057_50570502_33_dialog_content = "ขอโทษครับ/ค่ะ ทั้งหมดที่ฉันคิดได้ในเวลานั้นคือจะทำอาหารเมนูอะไร...",
